// Netlify Scheduled Function: triggers a site rebuild once a day so
// rss.html (generated by generate_rss_page.py at build time) actually
// refreshes on a schedule, instead of only updating whenever someone next
// pushes a commit or edits content through /admin.
//
// One-time setup required (can't be done from code):
//   1. In the Netlify dashboard: Site settings -> Build & deploy -> Build
//      hooks -> Add build hook. Name it anything (e.g. "RSS refresh").
//   2. Copy the generated URL.
//   3. Site settings -> Environment variables -> add RSS_REBUILD_HOOK_URL
//      set to that URL.
// Once both exist, this function runs automatically — no further action
// needed. Change the `schedule` string below to adjust how often it runs
// (cron syntax; this default is "once a day at 13:00 UTC").

export const config = {
  schedule: "0 13 * * *",
};

export default async () => {
  const hookUrl = process.env.RSS_REBUILD_HOOK_URL;

  if (!hookUrl) {
    console.warn(
      "scheduled-rss-rebuild: RSS_REBUILD_HOOK_URL is not set, skipping. " +
      "See the comment at the top of this file for one-time setup steps."
    );
    return;
  }

  const response = await fetch(hookUrl, { method: "POST" });
  console.log(`scheduled-rss-rebuild: build hook responded ${response.status}`);
};
